import Foundation

/// Resolves the monorepo workspace root by walking up from this test
/// file's location until a `pnpm-workspace.yaml` marker is found.
/// Exposes absolute paths to the cross-language fixtures generated by
/// spec 037:
///
/// - `packages/test-fixtures-sdk-parity/fixtures/parity-corpus.json`
/// - `packages/test-fixtures-sdk-parity/fixtures/parity-configs.json`
/// - `packages/test-fixtures-sdk-parity/fixtures/cache-key-fixtures.json`
///
/// Mirrors the Rust + Ruby + Go test-side helpers so the same fixture
/// loading pattern is used across every SDK.
enum WorkspaceRoot {
    /// Returns the absolute URL to the monorepo root. Panics if the
    /// marker file cannot be located above this source file (tests
    /// MUST run from within the monorepo).
    static func url() -> URL {
        let start = URL(fileURLWithPath: #filePath)
        var dir = start.deletingLastPathComponent()
        while true {
            let marker = dir.appendingPathComponent("pnpm-workspace.yaml")
            if FileManager.default.fileExists(atPath: marker.path) {
                return dir
            }
            let parent = dir.deletingLastPathComponent()
            if parent.path == dir.path {
                fatalError(
                    "WorkspaceRoot.url: could not find pnpm-workspace.yaml above "
                        + "\(start.path) — tests must run from within the monorepo."
                )
            }
            dir = parent
        }
    }

    /// Absolute path to the 58-tuple parity corpus.
    static var parityCorpusPath: URL {
        url().appendingPathComponent(
            "packages/test-fixtures-sdk-parity/fixtures/parity-corpus.json")
    }

    /// Absolute path to the canonical parity configs.
    static var parityConfigsPath: URL {
        url().appendingPathComponent(
            "packages/test-fixtures-sdk-parity/fixtures/parity-configs.json")
    }

    /// Absolute path to the cross-language cache-key fixtures.
    static var cacheKeyFixturesPath: URL {
        url().appendingPathComponent(
            "packages/test-fixtures-sdk-parity/fixtures/cache-key-fixtures.json")
    }

    /// Absolute path to the shared SDK-key accept/reject list (#802).
    static var sdkKeyShapesPath: URL {
        url().appendingPathComponent(
            "packages/test-fixtures-sdk-parity/fixtures/sdk-key-shapes.json")
    }

    /// Absolute path to the 13-tuple typed parity corpus (spec 073).
    static var parityCorpusTypedPath: URL {
        url().appendingPathComponent(
            "packages/test-fixtures-sdk-parity/fixtures/parity-corpus-typed.json")
    }

    /// Absolute path to the typed parity configs (spec 073).
    static var parityConfigsTypedPath: URL {
        url().appendingPathComponent(
            "packages/test-fixtures-sdk-parity/fixtures/parity-configs-typed.json")
    }

    /// Absolute path to the 8-tuple targeting-rule parity corpus
    /// (spec 135 / #435 US3).
    static var parityCorpusRulesPath: URL {
        url().appendingPathComponent(
            "packages/test-fixtures-sdk-parity/fixtures/parity-corpus-rules.json")
    }

    /// Absolute path to the full-config rule parity configs
    /// (spec 135 / #435 US3 — `injectionMode: "full-config"`).
    static var parityConfigsRulesPath: URL {
        url().appendingPathComponent(
            "packages/test-fixtures-sdk-parity/fixtures/parity-configs-rules.json")
    }

    /// Absolute path into the vendored upstream ConfigCat conformance corpus
    /// (`packages/test-fixtures-sdk-parity/fixtures/upstream/`), shared
    /// read-only with specs 117-126. The corpus test
    /// (``EvaluatorUpstreamCorpusTests``) reads the testmatrix CSVs +
    /// `evaluationlog/` + `comparison_*.json` through this accessor.
    static func upstreamPath(_ name: String = "") -> URL {
        let base = url().appendingPathComponent(
            "packages/test-fixtures-sdk-parity/fixtures/upstream")
        return name.isEmpty ? base : base.appendingPathComponent(name)
    }

    /// Read + JSON-decode a file under the upstream corpus directory.
    static func upstreamJson(_ relativePath: String) -> [String: Any] {
        let data = try! Data(contentsOf: upstreamPath(relativePath))
        let obj = try! JSONSerialization.jsonObject(with: data, options: [])
        guard let dict = obj as? [String: Any] else {
            fatalError("upstreamJson: root of \(relativePath) is not a JSON object")
        }
        return dict
    }

    /// Read a UTF-8 text file under the upstream corpus directory (the
    /// testmatrix CSVs).
    static func upstreamText(_ relativePath: String) -> String {
        let data = try! Data(contentsOf: upstreamPath(relativePath))
        return String(decoding: data, as: UTF8.self)
    }
}
